import React from 'react';
import { SEO, BOOK_TITLES } from '../../constants';
import { useSEO } from '../../hooks/useSEO';
import styles from './page-books.module.css';

export const PageBooks = () => {
  const seo = {
    ...SEO.books,
    schemaLD: {
      "@context": "https://schema.org",
      "@type": "CollectionPage",
      "name": "Разобранные книги — Нормальный книжный клуб",
      "description": "Архив всех книг, которые мы разбирали в клубе. Подробные конспекты, ключевые идеи, цитаты и выводы по каждой книге.",
      "url": "https://masha-normalno.ru/books",
      "image": "https://masha-normalno.ru/og-image-books.svg",
      "mainEntity": {
        "@type": "ItemList",
        "itemListElement": Object.entries(BOOK_TITLES).map(([key, title], index) => ({
          "@type": "ListItem",
          "position": index + 1,
          "item": {
            "@type": "Book",
            "name": title,
            "url": `https://masha-normalno.ru/books/${key}`
          }
        }))
      }
    }
  };

  useSEO(seo);

  const books = Object.entries(BOOK_TITLES).map(([key, title]) => ({
    key, title, slug: key
  }));

  return (
    <div className={styles.pageBooks}>
      <section className={styles.hero} id="books">
        <h1 className={styles.title}>Разобранные книги</h1>
        <p className={styles.subtitle}>
          Архив всех книг, которые мы читали и разбирали в клубе.
          У каждой — конспект, ключевые идеи и выводы.
        </p>
      </section>

      <section className={styles.grid} aria-label="Список разобранных книг">
        {books.map(({ key, title, slug }) => (
          <article key={key} id={slug} className={styles.bookCard}>
            <h2 className={styles.bookTitle}>{title}</h2>
            <a href={`#${slug}`} className={styles.bookLink}>
              Читать конспект
            </a>
          </article>
        ))}
      </section>

      <section className={styles.cta}>
        <p>Хотите предложить книгу или присоединиться к разбору?</p>
        <a href="/#contacts" className={styles.ctaButton}>Записаться на встречу</a>
      </section>
    </div>
  );
};